  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPM 流程实例编号',
  `approval_time` datetime DEFAULT NULL COMMENT '审批完成时间',
