--
-- Table structure for table `hrm_performance_assessment_quota_score`
--

DROP TABLE IF EXISTS `hrm_performance_assessment_quota_score`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_performance_assessment_quota_score` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `assessment_stage_id` bigint NOT NULL COMMENT '员工绩效考核阶段编号',
  `assessment_quota_id` bigint NOT NULL COMMENT '员工绩效考核指标编号',
  `score` decimal(10,2) NOT NULL COMMENT '指标得分',
  `comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标评语',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_quota_score_quota_id` (`assessment_quota_id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_quota_score_stage_quota` (`assessment_stage_id`,`assessment_quota_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 员工绩效考核指标评分表';
/*!40101 SET character_set_client = @saved_cs_client */;

