DROP TABLE IF EXISTS `hrm_performance_assessment_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_performance_assessment_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `illustrate` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模板说明',
  `score_calculation` tinyint DEFAULT '1' COMMENT '计分方式：1 加权计算',
  `upper_limit_type` tinyint DEFAULT '0' COMMENT '上限类型：0 不限制，1 固定分',
  `upper_limit_score` decimal(10,2) DEFAULT '100.00' COMMENT '分数上限',
  `dimension_count` int DEFAULT '0' COMMENT '维度数',
  `quota_count` int DEFAULT '0' COMMENT '指标数',
  `dimensions` json NOT NULL COMMENT '考核维度配置',
  `status` tinyint DEFAULT '0' COMMENT '状态，参见 common_status',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_performance_assessment_template_name` (`name`) USING BTREE,
  KEY `idx_hrm_perf_assessment_template_status_name` (`status`,`name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 绩效考核模板表';
