  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_performance_result_template_name` (`name`) USING BTREE,
  KEY `idx_hrm_perf_result_template_status_name` (`status`,`name`) USING BTREE
